public int minOperations(String[] logs) {
    // Initialize variables to keep track of the current depth and the minimum number of steps
    int currentDepth = 0;
    int minSteps = 0;

    // Iterate through the logs and evaluate the corresponding operation
    for (String log : logs) {
        // If the log is a directory operation (i.e., it ends with '/'), increment the current depth
        if (log.endsWith("/")) {
            currentDepth++;
        // Otherwise, if the log is a return operation (i.e., it is '../'), decrement the current depth
        } else if (log.equals("../")) {
            currentDepth--;
        }

        // Keep track of the minimum number of steps required to return to the main folder
        minSteps = Math.min(minSteps, currentDepth);
    }

    return minSteps;
}

public String getSmallestString(int n, int k) {
    // Initialize an array to store the characters of the string
    char[] chars = new char[n];

    // Initialize the value of the first character
    int value = 1;

    // Fill the array with characters, starting from the second character
    for (int i = 1; i < n; i++) {
        // Calculate the character value based on the previous value and the position of the character
        value += i;

        // Check if the value is greater than the requested value
        if (value > k) {
            // If the value is greater, calculate the difference between the requested value and the previous value
            int diff = k - (value - i);

            // Set the character value to the difference
            value = diff;

            // Skip the next character
            i++;
        }

        // Set the character to its corresponding value
        chars[i] = (char) (value + 'a' - 1);
    }

    // Return the string formed by the characters in the array
    return new String(chars);
}

