public static int[] diagonalOrder(int[][] mat) {
  int n = mat.length;
  int[] output = new int[n * n];
  int count = 0;
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      if (i == j) {
        output[count++] = mat[i][j];
      } else if (i + j == n - 1) {
        output[count++] = mat[i][j];
      }
    }
  }
  return output;
}

public static int findSmallestInteger(int n) {
if (n < 10) {
return -1;
}

int[] digits = new int[10];
for (int i = 0; i < 10; i++) {
digits[i] = (n % 10) + 1;
n /= 10;
}

Arrays.sort(digits);

int smallest = 0;
for (int i = 0; i < 10; i++) {
smallest = smallest * 10 + digits[i];
}

if (smallest > n) {
return smallest;
} else {
return -1;
}
}

public static List<String> centerSymmetricNumbers(int n) {
        // Validate input
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Initialize result list
        List<String> result = new ArrayList<>();

        // Loop through all possible numbers of length n
        for (int i = 0; i < (int) Math.pow(10, n); i++) {
            // If the number is center symmetric, add it to the result list
            if (isCenterSymmetric(i, n)) {
                result.add(String.valueOf(i));
            }
        }

        return result;
    }

public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        throw new IllegalArgumentException("Input array must contain exactly 3 points.");
    }
    int[] a = points[0], b = points[1], c = points[2];
    if (a[0] == b[0] || a[1] == b[1] || b[0] == c[0] || b[1] == c[1]) {
        throw new IllegalArgumentException("Input points must be distinct.");
    }
    return a[0] * (b[1] - c[1]) + b[0] * (c[1] - a[1]) + c[0] * (a[1] - b[1]) < 0;
}

public static int findNthUglyNumber(int n) {
    // Base case: n = 1
    if (n == 1) {
        return 1;
    }

    // Find the nth prime number
    int prime = findNthPrime(n);

    // Find the nth fibonacci number
    int fibonacci = findNthFibonacci(n);

    // Return the least common multiple of the prime and fibonacci numbers
    return lcm(prime, fibonacci);
}

public static int calculateEnergy(String s) {
    if (s.length() == 0) {
        return 0;
    }

    int maxLength = 1;
    int length = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            length++;
        } else {
            maxLength = Math.max(maxLength, length);
            length = 1;
        }
    }

    return Math.max(maxLength, length);
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        result.add(i);
    }
    result.sort((a, b) -> {
        return a.toString().compareTo(b.toString());
    });
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null) {
        throw new IllegalArgumentException("nums cannot be null.");
    }

    // Initialize an empty set to store unique values
    Set<Integer> uniqueValues = new HashSet<>();

    // Loop through the input array
    for (int num : nums) {
        // If the current value is not in the set, add it to the set and sum it up
        if (!uniqueValues.contains(num)) {
            uniqueValues.add(num);
        }
    }

    // Calculate the sum of the unique values
    int sum = 0;
    for (int value : uniqueValues) {
        sum += value;
    }

    return sum;
}

void minPerfectSquareSum(int n) {
    // Initialize an array to store the counts of each perfect square number
    int[] counts = new int[n + 1];

    // Pre-populate the array with zeroes
    for (int i = 0; i <= n; i++) {
        counts[i] = 0;
    }

    // Iterate through each perfect square number and its square root
    for (int i = 1; i * i <= n; i++) {
        // Calculate the square root of the current perfect square number
        int squareRoot = (int) Math.sqrt(i * i);

        // If the square root is a perfect square, increment the count
        if (squareRoot * squareRoot == i * i) {
            counts[i]++;
        }
    }

    // Count the number of perfect square numbers that sum up to n
    int minCount = Integer.MAX_VALUE;
    for (int i = 1; i <= n; i++) {
        if (counts[i] < minCount) {
            minCount = counts[i];
        }
    }

    // Return the minimum number of perfect square numbers
    return minCount;
}

public static String reverseWords(String s) {
    // Split the input string into an array of words using spaces as delimiters
    String[] words = s.split(" ");

    // Create a new string builder to store the reversed words
    StringBuilder sb = new StringBuilder();

    // Iterate over the array of words
    for (int i = 0; i < words.length; i++) {
        // Reverse the current word
        String word = new StringBuilder(words[i]).reverse().toString();

        // Add the reversed word to the string builder
        sb.append(word);

        // Add a space if there are more words to come
        if (i < words.length - 1) {
            sb.append(" ");
        }
    }

    // Return the reversed string
    return sb.toString();
}
